"""
Utility functions for the design space exploration optimizer.

This module contains helper functions used by the optimizer module,
including geometry distance calculations and lookup dictionary builders.
"""


# Cable length table (shortest path on the harness channel graph), keyed by the Point.ref ids.
# Loaded by set_distance_table(); without it, distances fall back to the Manhattan metric.
_DISTANCE_TABLE = None


def set_distance_table(ids, matrix):
    """Install the cable length table generated by tools/vehicle_layout/generate_layout.py."""
    global _DISTANCE_TABLE
    index = {i: k for k, i in enumerate(ids)}
    _DISTANCE_TABLE = (index, matrix)


def get_distance(loc1, loc2):
    """
    Cable length between two points.

    If a channel-graph distance table is loaded and both points carry a ref id in it, the length is the
    shortest path along the harness channels (plus the drops to the channels). Otherwise the 3D Manhattan
    distance is used. Returns 0.0 if either point is None.
    """
    if loc1 is None or loc2 is None:
        return 0.0
    if _DISTANCE_TABLE is not None:
        index, matrix = _DISTANCE_TABLE
        a, b = getattr(loc1, 'ref', None), getattr(loc2, 'ref', None)
        if a in index and b in index:
            return matrix[index[a]][index[b]]
    manhattan_dist, _ = loc1.dist(loc2)
    return manhattan_dist

def build_sensor_lookup(sensors):
    """
    Create a lookup dictionary for sensors by their ID.
    
    Args:
        sensors: List of sensor objects, each with an `id` attribute
    
    Returns:
        dict: Dictionary mapping sensor IDs to sensor objects
    """
    return {s.id: s for s in sensors}

def build_actuator_lookup(actuators):
    """
    Create a lookup dictionary for actuators by their ID.
    
    Args:
        actuators: List of actuator objects, each with an `id` attribute
    
    Returns:
        dict: Dictionary mapping actuator IDs to actuator objects
    """
    return {a.id: a for a in actuators}

def build_cost_map(cable_types):
    """
    Create a cost-per-meter lookup dictionary from cable types.
    
    Args:
        cable_types: Dict mapping cable type names to cable type objects
                    with 'cost_per_meter' attribute
    
    Returns:
        dict: Dictionary mapping cable type names to their cost_per_meter values
    """
    return {name: ct.cost_per_meter for name, ct in cable_types.items()}


def build_latency_map(cable_types):
    """
    Create a latency-per-meter lookup dictionary from cable types.
    
    Args:
        cable_types: Dict mapping cable type names to cable type objects
                    with 'latency_per_meter' attribute
    
    Returns:
        dict: Dictionary mapping cable type names to their latency_per_meter values
    """
    return {name: ct.latency_per_meter for name, ct in cable_types.items()}


def flow_routes(net, getv):
    """Per flow of the current solution: (start site, end site, cable type, index of the selected path) or None when
    both ends share a site; the path index is None when no path of the pair and type is selected. getv(var) returns
    the value of a variable (callback solution or .X)."""
    routes = {}
    for t, (src, dst) in net['flow_ends'].items():
        u = next((k for k, var in src.items() if getv(var) > 0.5), None)
        v = next((k for k, var in dst.items() if getv(var) > 0.5), None)
        if u is None or v is None or u == v:
            routes[t] = None
            continue
        elig = net['flow_elig'][t]
        w_if = elig[0] if len(elig) == 1 else max(elig, key=lambda n: getv(net['w'][t, n]))
        pair = (min(u, v), max(u, v))
        plist = net['paths'][pair + (w_if,)]
        chosen = [p for p in range(len(plist)) if getv(net['sel'][pair + (w_if, p)]) > 0.5]
        routes[t] = (u, v, w_if, chosen[0] if chosen else None)
    return routes


def crossing_latency_ms(net, t, w_if, hops):
    """Network latency of flow t over `hops` links of type w_if: hops * (message kbit / bit rate + per-hop bound), with
    the --robust_latency safety factor and the synchronisation / platform constants of configs/uncertainty.json."""
    lat = net['lat']
    base = hops * (net['kbit'][t] / net['cap_of'][w_if] + net['hop_ms'][w_if])
    return base * lat['factor'] + lat['sync'] + lat['platform'] if lat['robust'] else base


def failure_report(net, scs, locations, getv, uncertainty=None):
    """Per single-failure scenario of the solution: the element, the cold standbys it activates and the load they add
    per cell (CPU, DMIPS), and the network latency of every chain over the surviving instances against its degraded
    bound. Mirrors the checks of the solver callback (survival, degraded latency) for reporting."""
    routes = flow_routes(net, getv)
    n_locs = len(locations)
    pos_x = {}
    for (i, j), var in net['x_vars'].items():
        if getv(var) > 0.5:
            pos_x[i] = j
    pos_r = {i: next((j for (ii, j), var in net['r'].items() if ii == i and getv(var) > 0.5), None) for i in net['critical']}
    hot_val = {i: (1.0 if net['hot'][i] is None else getv(net['hot'][i])) for i in net['critical']}
    cells_on = {j for j in range(n_locs) if getv(net['y_vars'][j]) > 0.5}
    switches = {j for j in range(n_locs) if net['switch_vars'].get(j) is not None and getv(net['switch_vars'][j]) > 0.5}
    used_links = {(min(u, v), max(u, v), w_if) for rt in routes.values() if rt for u, v, w_if, _p in [rt]}
    classes = set(net['fail_cfg'].get('classes', ['cell', 'switch', 'cable']))
    scenarios = []
    if 'cell' in classes:
        scenarios += [('cell', c) for c in sorted(cells_on | switches)]
    if 'switch' in classes:
        scenarios += [('switch', c) for c in sorted(switches)]
    if 'cable' in classes:
        scenarios += [('cable', k) for k in sorted(used_links)]
    order = {'SC_SC': [('x', 'x'), ('x', 'r'), ('r', 'x'), ('r', 'r')], 'SENS_SC': [('a', 'x'), ('a', 'r')], 'SC_ACT': [('x', 'a'), ('r', 'a')]}

    def ends(t):
        src, dst = net['flow_ends'][t]
        return (next((k for k, var in src.items() if getv(var) > 0.5), None), next((k for k, var in dst.items() if getv(var) > 0.5), None))

    def alive(t, kind, elem):
        u, v = ends(t)
        if u is None or v is None or (kind == 'cell' and elem in (u, v)):
            return False
        if u == v:
            return True
        rt = routes.get(t)
        if rt is None or rt[3] is None:
            return False
        _u, _v, w_if, p = rt
        path = net['paths'][(min(u, v), max(u, v), w_if)][p]
        if kind in ('cell', 'switch') and elem in path[1:-1]:
            return False
        if kind == 'switch' and w_if == 'ETH' and elem in (u, v):
            return False
        if kind == 'cable' and elem[2] == w_if and any({pa, pb} == {elem[0], elem[1]} for pa, pb in zip(path, path[1:])):
            return False
        return True

    report = []
    for kind, elem in scenarios:
        entry = {'kind': kind, 'element': (locations[elem].id if kind != 'cable' else f"{locations[elem[0]].id}-{locations[elem[1]].id} {elem[2]}")}
        if kind == 'cell':
            act = [i for i in net['critical'] if pos_x.get(i) == elem and pos_r.get(i) is not None and hot_val[i] < 0.5]
            entry['activated_cold_standbys'] = [scs[i].id for i in act]
            load = {}
            for i in act:
                load[locations[pos_r[i]].id] = load.get(locations[pos_r[i]].id, 0.0) + scs[i].cpu_req * sw_multiplier(scs[i], uncertainty)
            entry['added_cpu_load'] = {k: round(v) for k, v in load.items()}
        chains = {}
        for ch in net.get('chains', []):
            total, broken = 0.0, False
            for t_base in ch['flows']:
                picked = None
                for key in order[net['flow_meta'][t_base]['type']]:
                    t = net['base_variants'][t_base].get(key)
                    if t is not None and alive(t, kind, elem):
                        picked = t
                        break
                if picked is None:
                    broken = True
                    break
                u, v = ends(picked)
                if u != v:
                    _u, _v, w_if, p = routes[picked]
                    total += crossing_latency_ms(net, picked, w_if, len(net['paths'][(min(u, v), max(u, v), w_if)][p]) - 1)
            status = 'broken (non-critical member lost)' if broken else ('ok' if total <= ch['degraded'] + 1e-6 else 'over bound')
            chains[ch['id']] = {'latency_ms': None if broken else round(total, 3), 'degraded_bound_ms': ch['degraded'],
                                'ok': status != 'over bound', 'status': status}
        entry['chains'] = chains
        worst = max((c for c in chains.values() if c['latency_ms'] is not None), key=lambda c: c['latency_ms'] / c['degraded_bound_ms'], default=None)
        entry['worst_chain_ratio'] = round(worst['latency_ms'] / worst['degraded_bound_ms'], 3) if worst else None
        report.append(entry)
    return report


def chain_latencies(net, routes):
    """Network latency of every cause-effect chain (configs/chains.json) for the routes of a solution."""
    out = {}
    for ch in net.get('chains', []):
        total, crossings = 0.0, []
        for t in ch['flows']:
            r = routes.get(t)
            if r is None or r[3] is None:
                continue
            u, v, w_if, p = r
            hops = len(net['paths'][(min(u, v), max(u, v), w_if)][p]) - 1
            ms = crossing_latency_ms(net, t, w_if, hops)
            total += ms
            crossings.append({'flow': t, 'from': net['site_ids'][u], 'to': net['site_ids'][v], 'iface': w_if, 'hops': hops, 'ms': round(ms, 3)})
        out[ch['id']] = {'latency_ms': round(total, 3), 'budget_ms': ch['budget'], 'ok': bool(total <= ch['budget'] + 1e-6),
                         'crossings': crossings}
    return out


# ============================================================================
# UNCERTAINTY HELPERS AND PARTITION PACKING
# ============================================================================

def sw_multiplier(sc, uncertainty):
    """Resource demand multiplier of an SC: the --sw_margin margins (listed domains only) times the --growth factor
    1 + alpha * profile[domain] at the growth level uncertainty['growth_alpha'] (configs/uncertainty.json: growth)."""
    unc = uncertainty or {}
    m = 1.0
    domain = str(getattr(sc, 'domain', '') or '').strip()
    if unc.get('sw_margin'):
        cfg = unc.get('params', {}).get('sw_margin', {})
        if domain.upper() in {str(d).strip().upper() for d in cfg.get('domains', [])}:
            margins = {int(k): float(v) for k, v in cfg.get('asil_margins', {}).items()}
            m_asil = margins.get(int(getattr(sc, 'asil_req', 0)), float(cfg['default_asil_margin']))
            m_ai = float(cfg['ai_margin']) if (cfg['ai_hw_feature'] in (getattr(sc, 'hw_required', None) or [])) else 0.0
            m *= 1.0 + m_asil + m_ai
    if unc.get('growth'):
        cfg = unc.get('params', {}).get('growth', {})
        alpha = float(unc.get('growth_alpha', 0.0))
        m *= 1.0 + alpha * float(cfg.get('profiles', {}).get(domain, cfg.get('default_profile', 0.0)))
    return m


def site_derating(location, uncertainty):
    """Capacity derating of a site under --derating (its thermal-class factor), else 1.0."""
    if not (uncertainty or {}).get('derating'):
        return 1.0
    return max(0.0, float(getattr(location, 'health_factor', 1.0)))


def _first_fit_decreasing(members, demand, bin_cap, n_bins):
    """Pack items (dict of resource demands) into n_bins bins; returns {item: bin} or None."""
    active = [r for r in bin_cap if bin_cap[r] > 0]

    def largest(i):
        return max((demand[i][r] / bin_cap[r] for r in active), default=0.0)

    load = [{r: 0.0 for r in active} for _ in range(n_bins)]
    slots = {}
    for i in sorted(members, key=largest, reverse=True):
        for b in range(n_bins):
            if all(load[b][r] + demand[i][r] <= bin_cap[r] * (1.0 + 1e-9) + 1e-9 for r in active):
                for r in active:
                    load[b][r] += demand[i][r]
                slots[i] = b
                break
        else:
            return None
    return slots


def _exact_packing(members, demand, bin_cap, n_bins):
    """Exact vector bin packing (small MILP); returns {item: bin} or None if no packing exists."""
    import gurobipy as gp
    from gurobipy import GRB
    if n_bins <= 0:
        return None
    m = gp.Model("partition_packing")
    m.setParam('OutputFlag', 0)
    u = {(i, b): m.addVar(vtype=GRB.BINARY) for i in members for b in range(n_bins)}
    for i in members:
        m.addConstr(gp.quicksum(u[i, b] for b in range(n_bins)) == 1)
    for b in range(n_bins):
        for r, cap in bin_cap.items():
            if cap > 0:
                m.addConstr(gp.quicksum(demand[i][r] * u[i, b] for i in members) <= cap)
    m.optimize()
    if m.SolCount == 0:
        return None
    return {i: next(b for b in range(n_bins) if u[i, b].X > 0.5) for i in members}


def pack_partitions(x, P, scs, locations, partitions, uncertainty=None, standby=None):
    """
    Give every hosted SC a concrete partition slot "<site>_asil<a>_p<k>" inside the P[j, a] partitions the model
    opened. The model's capacity constraint pools the partitions of one ASIL at a site (demand <= P * capacity),
    which is a relaxation of bin packing; this function checks it with first-fit decreasing and, if that fails,
    an exact packing model.

    Returns (partition_map, failed): failed lists (j, a, sc_indices, P_value) of groups that no packing fits;
    the optimiser adds a cut for each and solves again.
    """
    caps = {res: float(partitions.get(f'{res}_cap', 0) or 0) for res in ('cpu', 'ram', 'rom')}
    groups = {}   # (cell, ASIL) -> [(member key, variable)]; members are primaries (i, 'x') and hot standbys (i, 'r')
    for (i, j), var in x.items():
        if var.X > 0.5:
            groups.setdefault((j, scs[i].asil_req), []).append(((i, 'x'), var))
    for (i, j), var in (standby or {}).items():
        if var.X > 0.5:
            groups.setdefault((j, scs[i].asil_req), []).append(((i, 'r'), var))
    partition_map, failed = {}, []
    for (j, a), members in sorted(groups.items()):
        n_bins = int(round(P[j, a].X))
        h = site_derating(locations[j], uncertainty)
        bin_cap = {res: caps[res] * h for res in caps}
        keys = [k for k, _v in members]
        demand = {k: {res: float(getattr(scs[k[0]], f'{res}_req', 0) or 0) * sw_multiplier(scs[k[0]], uncertainty) for res in caps}
                  for k in keys}
        slots = _first_fit_decreasing(keys, demand, bin_cap, n_bins)
        if slots is None:
            slots = _exact_packing(keys, demand, bin_cap, n_bins)
        if slots is None:
            failed.append((j, a, list(members), n_bins))
            slots = {k: 0 for k in keys}
        for (i, inst), b in slots.items():
            partition_map[scs[i].id + ('@standby' if inst == 'r' else '')] = f"{locations[j].id}_asil{a}_p{b}"
    return partition_map, failed


# ============================================================================
# COST CALCULATION UTILITIES
# ============================================================================

def calculate_sensor_actuator_cable_costs(x, scs, locations, sensors, actuators, cable_types, attach_s=None, attach_a=None, shared_attach_s=None, shared_attach_a=None, shared_trunk_len=None, shared_extra_trunk_len=None):
    """
    Calculate total cable costs and distances for sensor/actuator connections.
    
    Iterates through all hosted software components (x variables) and calculates
    the cost and distance of cables connecting sensors and actuators to their
    assigned locations.
    
    Args:
        x: Dict of placement variables with keys (sc_idx, loc_idx)
        scs: List of software component objects, each with 'sensors' and 'actuators' attributes
        locations: List of location/ECU objects
        sensors: List of sensor objects with 'id', 'location', and 'interface' attributes
        actuators: List of actuator objects with 'id', 'location', and 'interface' attributes
        cable_types: Dict mapping cable type names to cable type objects with 'cost_per_meter'
    
    Returns:
        tuple: (cable_length, cable_cost)
            - cable_length: Total distance of all sensor/actuator cables (float)
            - cable_cost: Total cost of all sensor/actuator cables (float)
    """
    cable_length = 0.0
    cable_cost = 0.0
    cost_map = {name: ct.cost_per_meter for name, ct in cable_types.items()}
    sensor_lookup = build_sensor_lookup(sensors)
    actuator_lookup = build_actuator_lookup(actuators)
    
    shared_bus_ifaces = {'CAN', 'LIN', 'FLEXRAY'}

    for (i, j), var in x.items():
        if var.X > 0.5:
            sc = scs[i]
            
            # Sensor cable costs and distances
            for s_id in (sc.sensors or []):
                sensor = sensor_lookup.get(s_id)
                if sensor and sensor.location:
                    if attach_s is not None and getattr(sensor, 'interface', None) == 'ETH':
                        continue
                    if shared_attach_s is not None and getattr(sensor, 'interface', None) in shared_bus_ifaces:
                        continue
                    dist = get_distance(sensor.location, locations[j].location)
                    cable_length += dist
                    cable_cost += dist * cost_map.get(sensor.interface, 0.0)
            
            # Actuator cable costs and distances
            for a_id in (sc.actuators or []):
                actuator = actuator_lookup.get(a_id)
                if actuator and actuator.location:
                    if attach_a is not None and getattr(actuator, 'interface', None) == 'ETH':
                        continue
                    if shared_attach_a is not None and getattr(actuator, 'interface', None) in shared_bus_ifaces:
                        continue
                    dist = get_distance(actuator.location, locations[j].location)
                    cable_length += dist
                    cable_cost += dist * cost_map.get(actuator.interface, 0.0)

    # ETH attachment cables
    if attach_s:
        for (si, j), av in attach_s.items():
            if av.X > 0.5:
                s = sensors[si]
                if not getattr(s, 'location', None):
                    continue
                dist = get_distance(s.location, locations[j].location)
                cable_length += dist
                cable_cost += dist * cost_map.get(getattr(s, 'interface', 'ETH'), 0.0)

    if attach_a:
        for (ai, j), av in attach_a.items():
            if av.X > 0.5:
                aobj = actuators[ai]
                if not getattr(aobj, 'location', None):
                    continue
                dist = get_distance(aobj.location, locations[j].location)
                cable_length += dist
                cable_cost += dist * cost_map.get(getattr(aobj, 'interface', 'ETH'), 0.0)

    # Shared-bus attachments (CAN/LIN/FLEXRAY)
    if shared_attach_s:
        for (si, j), av in shared_attach_s.items():
            if av.X > 0.5:
                s = sensors[si]
                if not getattr(s, 'location', None):
                    continue
                iface = getattr(s, 'interface', None)
                if iface not in shared_bus_ifaces:
                    continue
                dist = get_distance(s.location, locations[j].location)
                cable_length += dist
                cable_cost += dist * cost_map.get(iface, 0.0)

    if shared_attach_a:
        for (ai, j), av in shared_attach_a.items():
            if av.X > 0.5:
                aobj = actuators[ai]
                if not getattr(aobj, 'location', None):
                    continue
                iface = getattr(aobj, 'interface', None)
                if iface not in shared_bus_ifaces:
                    continue
                dist = get_distance(aobj.location, locations[j].location)
                cable_length += dist
                cable_cost += dist * cost_map.get(iface, 0.0)

    # Shared trunk length contribution (one main segment per location/interface)
    if shared_trunk_len:
        for (_j, iface), tv in shared_trunk_len.items():
            trunk_len = float(getattr(tv, 'X', 0.0) or 0.0)
            if trunk_len <= 1e-9:
                continue
            cable_length += trunk_len
            cable_cost += trunk_len * cost_map.get(iface, 0.0)

    # Extra trunk contribution when ASIL split opens a second shared bus segment
    if shared_extra_trunk_len:
        for (_j, iface), tv in shared_extra_trunk_len.items():
            trunk_len = float(getattr(tv, 'X', 0.0) or 0.0)
            if trunk_len <= 1e-9:
                continue
            cable_length += trunk_len
            cable_cost += trunk_len * cost_map.get(iface, 0.0)
    
    return cable_length, cable_cost


def calculate_partition_cost(P, partitions):
    """
    Calculate total partition cost from the partition count variables.

    Args:
        P: Dict of P variables with keys (location_idx, asil)
        partitions: Dict with key 'cost' representing the cost per partition

    Returns:
        float: Total partition cost
    """
    num_partitions_opened = sum(int(round(var.X)) for var in P.values())
    return num_partitions_opened * partitions.get('cost', 0)


def calculate_hardware_cost(hw_use, hardwares, locations):
    """
    Calculate total hardware cost based on opened hardware at locations.
    
    Args:
        hw_use: Dict of hw_use variables with keys (location_idx, hardware_name)
        hardwares: Dict mapping hardware names to their costs (float)
        locations: List of location/ECU objects
    
    Returns:
        tuple: (hw_cost, hw_opened list)
            - hw_cost: Total hardware cost (float)
            - hw_opened: List of opened hardware with format "HW_NAME@LOCATION_ID"
    """
    hw_opened = []
    for (j, h), var in hw_use.items():
        if var.X > 0.5:
            hw_opened.append(f"{h}@{locations[j].id}")
    
    hw_cost = sum(hardwares.get(hw_name.split('@')[0], 0) for hw_name in hw_opened)
    return hw_cost, hw_opened


def calculate_interface_cost(if_use, interfaces, locations):
    """
    Calculate total interface cost based on number of ports at locations.
    
    Args:
        if_use: Dict of if_use variables with keys (location_idx, interface_name)
        interfaces: Dict mapping interface names to interface objects with 'port_cost' attribute
        locations: List of location/ECU objects
    
    Returns:
        tuple: (if_cost, if_opened list)
            - if_cost: Total interface cost (float)
            - if_opened: List of opened interfaces with count, e.g., "3xETH@LOCATION_ID"
    """
    if_opened = []
    if_cost = 0.0
    for (j, i_name), var in if_use.items():
        if var.X > 0.1:  # Use a small epsilon for integer variables
            count = int(round(var.X))
            if_opened.append(f"{count}x{i_name}@{locations[j].id}")
            if_cost += count * interfaces[i_name].port_cost
    
    return if_cost, if_opened


def calculate_communication_cost(comm, locations, cable_types):
    """
    Calculate total communication cost for ECU-to-ECU connections.
    
    Calculates the cost of communication backbone links between locations
    based on distance and cable type.
    
    Args:
        comm: Dict of comm variables with keys (location_idx1, location_idx2, interface_name)
        locations: List of location/ECU objects
        cable_types: Dict mapping cable type names to cable type objects with 'cost_per_meter'
    
    Returns:
        float: Total communication cost
    """
    comm_cost = 0.0
    for (j1, j2, iface), var in comm.items():
        if var.X > 0.5:
            num_links = int(round(var.X))
            dist = get_distance(locations[j1].location, locations[j2].location)
            cost_per_link = dist * cable_types[iface].cost_per_meter
            comm_cost += num_links * cost_per_link
    
    return comm_cost


def extract_communication_links(comm, locations, min_link_value=0.5):
    """Extract opened ECU-to-ECU links from solved comm variables."""
    links = []
    for (j1, j2, iface), var in comm.items():
        if var.X > min_link_value:
            links.append({
                'src_loc': locations[j1].id,
                'dst_loc': locations[j2].id,
                'iface': iface,
                'count': int(round(var.X)),
            })
    return links



# ============================================================================
# SOLUTION EXTRACTION AND FORMATTING
# ============================================================================
def extract_solution(x, P, y, hw_use, if_use, comm, scs, locations, sensors, actuators,
                     cable_types, partitions, hardwares, interfaces, comm_matrix=None,
                     traffic_flows=None, net=None, attach_s=None, attach_a=None,
                     shared_attach_s=None, shared_attach_a=None, shared_trunk_len=None, shared_extra_trunk_len=None,
                     partition_map=None, standby=None, uncertainty=None):
        """
        Extract formatted solution dict from raw Gurobi model variables.
        
        This is a PRESENTATION LAYER function - converts raw optimization results 
        into a human-readable solution dictionary for visualization and reporting.
        
        Args:
            x: Dict of SC placement variables x[i, j]
            P: Dict of partition count variables P[j, a]
            y: Dict of site activation variables y[j]
            partition_map: {SC_id: partition_name} from pack_partitions (optional)
            hw_use: Dict of hardware opening variables
            if_use: Dict of interface opening variables
            comm: Dict of communication backbone variables
            scs: List of software component objects
            locations: List of location/ECU objects
            sensors: List of sensor objects
            actuators: List of actuator objects
            cable_types: Dict of cable type objects
            partitions: Dict with partition configuration
            hardwares: Dict mapping hardware names to costs
            interfaces: Dict mapping interface names to interface objects
            comm_matrix: Optional list of communication requirements
        
        Returns:
            dict: Formatted solution dictionary with keys:
                - assignment: {SC_id: location_id}
                - partitions: {SC_id: partition_name}
                - hw_cost, if_cost, cable_cost, comm_cost, partition_cost
                - total_cost
                - hw_features, interfaces (opened features)
                - num_locations_used, num_partitions, cable_length
                - status: 'OPTIMAL'
        """
        assignment_map = {}
        partition_map = dict(partition_map or {})
        num_locations_used = 0

        # Extract SC assignments from x; partition slots come from pack_partitions (fallback: slot 0)
        for (i, j), var in x.items():
            if var.X > 0.5:
                assignment_map[scs[i].id] = locations[j].id
                partition_map.setdefault(scs[i].id, f"{locations[j].id}_asil{scs[i].asil_req}_p0")
        # Standby instances (failures): cell, type and partition slot per critical SC
        standby_map = {}
        if standby:
            r_vars, hot_vars = standby
            for (i, j), var in r_vars.items():
                if var.X > 0.5:
                    kind = 'hot' if (hot_vars.get(i) is None or hot_vars[i].X > 0.5) else 'cold'
                    standby_map[scs[i].id] = {'cell': locations[j].id, 'type': kind,
                                              'partition': partition_map.get(scs[i].id + '@standby', f"{locations[j].id}_asil{scs[i].asil_req}_p0")}
            print(f"\n[DEBUG] Standby instances: {len(standby_map)} ({sum(1 for s in standby_map.values() if s['type'] == 'hot')} hot, "
                  f"{sum(1 for s in standby_map.values() if s['type'] == 'cold')} cold)")
        partition_map = {k: v for k, v in partition_map.items() if not k.endswith('@standby')}
        
        # DEBUG: Print SC placements and communication requirements
        print(f"\n[DEBUG] SC Placement Analysis:")
        print(f"  Total SCs assigned: {len(assignment_map)}")
        if comm_matrix:
            print(f"  Communication links required: {len(comm_matrix)}")
            for link in comm_matrix:
                src_id = link.get('src')
                dst_id = link.get('dst')
                vol = link.get('volume', 0)
                src_loc = assignment_map.get(src_id, 'NOT_ASSIGNED')
                dst_loc = assignment_map.get(dst_id, 'NOT_ASSIGNED')
                same_loc = (src_loc == dst_loc)
                print(f"    {src_id} ({src_loc}) -> {dst_id} ({dst_loc}) vol={vol} {'[SAME_LOC]' if same_loc else '[DIFFERENT_LOC]'}")
        
        # Partitions opened and fixed site cost
        num_partitions_opened = sum(int(round(var.X)) for var in P.values())
        site_fixed_cost = float(partitions.get('site_fixed_cost', 0) or 0)
        site_cost = site_fixed_cost * sum(1 for var in y.values() if var.X > 0.5)
        
        # Extract HW and interfaces opened
        hw_cost, hw_opened = calculate_hardware_cost(hw_use, hardwares, locations)
        
        # Debug: Check if SWITCH was selected
        switches_selected = [hw for hw in hw_opened if hw.startswith("SWITCH")]
        all_hw_available = list(hardwares.keys()) if hardwares else []
        if switches_selected:
            print(f"[DEBUG] SWITCH selected at: {switches_selected}")
        elif "SWITCH" in all_hw_available:
            print(f"[DEBUG] WARNING: SWITCH available but NOT selected in optimal solution")
        
        if_cost, if_opened = calculate_interface_cost(if_use, interfaces, locations)
        
        # Count locations used
        locs_used = set()
        for (i, j), var in x.items():
            if var.X > 0.5:
                locs_used.add(j)
        num_locations_used = len(locs_used)
        
        # Calculate cable costs and distances
        cable_length, cable_cost = calculate_sensor_actuator_cable_costs(
            x, scs, locations, sensors, actuators, cable_types,
            attach_s=attach_s, attach_a=attach_a,
            shared_attach_s=shared_attach_s, shared_attach_a=shared_attach_a,
            shared_trunk_len=shared_trunk_len,
            shared_extra_trunk_len=shared_extra_trunk_len
        )
        
        # Calculate partition and communication costs
        partition_cost = calculate_partition_cost(P, partitions)
        comm_cost = calculate_communication_cost(comm, locations, cable_types)
        comm_links = extract_communication_links(comm, locations)

        # Backbone (ECU-ECU) cable length, counted in the model's cable_distance_expr as well
        backbone_length = sum(
            int(round(var.X)) * get_distance(locations[j1].location, locations[j2].location)
            for (j1, j2, _iface), var in comm.items()
            if var.X > 0.5
        )
        peripheral_cable_length = cable_length
        cable_length = peripheral_cable_length + backbone_length

        # DEBUG: ETH peripheral attachments
        if attach_s:
            attached = []
            for (si, j), av in attach_s.items():
                if av.X > 0.5:
                    attached.append((sensors[si].id, locations[j].id))
            print("\n[DEBUG] ETH Sensor Attachments:")
            if not attached:
                print("  None")
            else:
                print(f"  Total: {len(attached)}")
                for sid, lid in attached[:20]:
                    print(f"  {sid} -> {lid}")
                if len(attached) > 20:
                    print(f"  ... ({len(attached) - 20} more)")

        if attach_a:
            attached = []
            for (ai, j), av in attach_a.items():
                if av.X > 0.5:
                    attached.append((actuators[ai].id, locations[j].id))
            print("\n[DEBUG] ETH Actuator Attachments:")
            if not attached:
                print("  None")
            else:
                print(f"  Total: {len(attached)}")
                for aid, lid in attached[:20]:
                    print(f"  {aid} -> {lid}")
                if len(attached) > 20:
                    print(f"  ... ({len(attached) - 20} more)")

        # DEBUG: Selected backbone links (comm)
        print(f"\n[DEBUG] Selected Backbone Links (comm):")
        if not comm_links:
            print("  No backbone links opened")
        else:
            # Stable sort by iface then endpoints
            def _lk_sort_key(lk):
                a, b = (lk['src_loc'], lk['dst_loc']) if lk['src_loc'] <= lk['dst_loc'] else (lk['dst_loc'], lk['src_loc'])
                return (lk.get('iface', ''), a, b)

            for lk in sorted(comm_links, key=_lk_sort_key):
                src_id = lk['src_loc']
                dst_id = lk['dst_loc']
                iface = lk.get('iface', '?')
                count = lk.get('count', 0)
                # Find indices for distance (safe fallback if ids are unexpected)
                src_idx = next((ii for ii, loc in enumerate(locations) if loc.id == src_id), None)
                dst_idx = next((ii for ii, loc in enumerate(locations) if loc.id == dst_id), None)
                if src_idx is not None and dst_idx is not None:
                    dist = get_distance(locations[src_idx].location, locations[dst_idx].location)
                    cpm = cable_types.get(iface).cost_per_meter if cable_types.get(iface) else 0.0
                    print(f"  {src_id} <-> {dst_id} iface={iface} count={count} dist={dist:.2f} cost/link={dist * cpm:.2f}")
                else:
                    print(f"  {src_id} <-> {dst_id} iface={iface} count={count}")

        # Backbone routing: chosen candidate path and routed volume per site pair
        comm_link_peak_load = {}
        backbone_routes = []
        chain_latency = {}
        failure_scenarios = []
        print(f"\n[DEBUG] Backbone routing (site pairs with traffic):")
        if not net:
            print("  Routing unavailable (net not provided to extract_solution)")
        else:
            paths, sel = net['paths'], net['sel']
            arc_load = {}
            relayed = 0
            pair_dir_vol = {}
            # nominal pair volumes per cable type from the flow endpoints and the type choice w; a flow to or from a
            # cold standby carries nothing in the nominal state (its path must exist, the model does not load it)
            hot_val = {i: (1.0 if net['hot'][i] is None else net['hot'][i].X) for i in net.get('critical', [])}
            for t, (src, dst) in net['flow_ends'].items():
                u = next((k for k, var in src.items() if var.X > 0.5), None)
                v = next((k for k, var in dst.items() if var.X > 0.5), None)
                if u is None or v is None or u == v:
                    continue
                elig = net['flow_elig'][t]
                w_if = elig[0] if len(elig) == 1 else max(elig, key=lambda n: net['w'][t, n].X)
                pair = (min(u, v), max(u, v))
                tr = net['flow_meta'][t]
                silent = any(tr.get(inst_key, 'x') == 'r' and hot_val.get(tr[idx_key], 1.0) < 0.5
                             for inst_key, idx_key in (('src_inst', 'src_idx'), ('dst_inst', 'dst_idx')))
                vols = pair_dir_vol.setdefault(pair + (w_if,), [0.0, 0.0])
                if not silent:
                    vols[0 if (u, v) == pair else 1] += net['volumes'][t]
            for (u, v, w_if), plist in paths.items():
                chosen = [p for p in range(len(plist)) if sel[u, v, w_if, p].X > 0.5]
                if not chosen:
                    continue
                p = chosen[0]
                path = plist[p]
                if (u, v, w_if) not in pair_dir_vol:   # a selected path no flow uses needs no cable
                    continue
                vol_fwd, vol_rev = pair_dir_vol[(u, v, w_if)]
                for vol, seq in ((vol_fwd, path), (vol_rev, path[::-1])):
                    for a, b in zip(seq, seq[1:]):
                        arc_load[(a, b, w_if)] = arc_load.get((a, b, w_if), 0.0) + vol
                ids = [locations[j].id for j in path]
                relayed += int(len(path) > 2)
                backbone_routes.append({'src_loc': ids[0], 'dst_loc': ids[-1], 'iface': w_if, 'path': ids,
                                        'volume_fwd': round(vol_fwd, 3), 'volume_rev': round(vol_rev, 3)})
                print(f"  {ids[0]} <-> {ids[-1]} [{w_if}]: {' -> '.join(ids)}  volume {vol_fwd:.1f} / {vol_rev:.1f}" + ("  (relayed)" if len(path) > 2 else ""))
            print(f"  Summary: {len(backbone_routes)} site pairs with traffic, {relayed} relayed")
            for (a, b, w_if), load in arc_load.items():
                key = f"{locations[min(a, b)].id}|{locations[max(a, b)].id}|{w_if}"
                comm_link_peak_load[key] = max(comm_link_peak_load.get(key, 0.0), float(load))
            if net.get('critical'):
                failure_scenarios = failure_report(net, scs, locations, lambda var: var.X, uncertainty)
                over = [e for e in failure_scenarios if any(c['status'] == 'over bound' for c in e['chains'].values())]
                broken = [e for e in failure_scenarios if any(c['status'].startswith('broken') for c in e['chains'].values())]
                print(f"\n[DEBUG] Failure scenarios: {len(failure_scenarios)} checked, {len(over)} with a chain over its degraded bound, "
                      f"{len(broken)} with a chain broken by a lost non-critical member; worst chain ratio "
                      f"{max((e['worst_chain_ratio'] or 0) for e in failure_scenarios):.2f}")
            if net.get('chains'):
                chain_latency = chain_latencies(net, flow_routes(net, lambda var: var.X))
                print(f"\n[DEBUG] Chain network latency (ms):")
                for cid, c in chain_latency.items():
                    print(f"  {cid:42s} {c['latency_ms']:8.3f} / budget {c['budget_ms']:7.1f}  crossings {len(c['crossings'])}  {'ok' if c['ok'] else 'VIOLATED'}")

        total_cost = partition_cost + site_cost + hw_cost + if_cost + cable_cost + comm_cost

        # Decision values an independent check needs (tools/check_solution.py): partitions per (site, ASIL), the
        # route and cable type of every data flow, and the shared-bus trunk lengths
        partition_counts = {f"{locations[j].id}_asil{a}": int(round(var.X)) for (j, a), var in P.items() if var.X > 0.5}
        flow_route_list = []
        if net:
            routes = flow_routes(net, lambda var: var.X)
            for t, tr in net['flow_meta'].items():
                if tr['type'] == 'SC_SC':
                    src, dst = scs[tr['src_idx']].id, scs[tr['dst_idx']].id
                elif tr['type'] == 'SENS_SC':
                    src, dst = sensors[tr['sensor_idx']].id, scs[tr['dst_idx']].id
                else:
                    src, dst = scs[tr['src_idx']].id, actuators[tr['act_idx']].id
                entry = {'type': tr['type'], 'src': src, 'dst': dst,
                         'src_inst': tr.get('src_inst', 'a' if tr['type'] == 'SENS_SC' else 'x'),
                         'dst_inst': tr.get('dst_inst', 'a' if tr['type'] == 'SC_ACT' else 'x'),
                         'iface': None, 'path': None}
                rt = routes.get(t)
                if rt is not None:
                    u, v, w_if, p_idx = rt
                    entry['iface'] = w_if
                    if p_idx is not None:
                        path = net['paths'][(min(u, v), max(u, v), w_if)][p_idx]
                        path = path if path[0] == u else path[::-1]
                        entry['path'] = [locations[k].id for k in path]
                flow_route_list.append(entry)
        shared_trunks = {}
        for (j, iface), tv in (shared_trunk_len or {}).items():
            main = float(getattr(tv, 'X', 0.0) or 0.0)
            extra = float(getattr((shared_extra_trunk_len or {}).get((j, iface)), 'X', 0.0) or 0.0)
            if main > 1e-9 or extra > 1e-9:
                shared_trunks[f"{locations[j].id}|{iface}"] = {'main': main, 'extra': extra}

        eth_sensor_attachments = {}
        if attach_s:
            for (si, j), av in attach_s.items():
                if av.X > 0.5:
                    eth_sensor_attachments[sensors[si].id] = locations[j].id

        eth_actuator_attachments = {}
        if attach_a:
            for (ai, j), av in attach_a.items():
                if av.X > 0.5:
                    eth_actuator_attachments[actuators[ai].id] = locations[j].id

        shared_sensor_attachments = {}
        if shared_attach_s:
            for (si, j), av in shared_attach_s.items():
                if av.X > 0.5:
                    shared_sensor_attachments[sensors[si].id] = locations[j].id

        shared_actuator_attachments = {}
        if shared_attach_a:
            for (ai, j), av in shared_attach_a.items():
                if av.X > 0.5:
                    shared_actuator_attachments[actuators[ai].id] = locations[j].id
        
        solution = {
            'assignment': assignment_map,
            'partitions': partition_map,
            'hardware_cost': hw_cost,  # For visualizer compatibility
            'hw_cost': hw_cost,
            'interface_cost': if_cost,
            'cable_cost': cable_cost,
            'comm_cost': comm_cost,
            'comm_links': comm_links,
            'comm_link_peak_load': comm_link_peak_load,
            'backbone_routes': backbone_routes,
            'chain_latency': chain_latency,
            'standby': standby_map,
            'failure_scenarios': failure_scenarios,
            'eth_sensor_attachments': eth_sensor_attachments,
            'eth_actuator_attachments': eth_actuator_attachments,
            'shared_sensor_attachments': shared_sensor_attachments,
            'shared_actuator_attachments': shared_actuator_attachments,
            'cable_length': cable_length,
            'peripheral_cable_length': peripheral_cable_length,
            'backbone_length': backbone_length,
            'total_cost': total_cost,
            'num_locations_used': num_locations_used,
            'num_candidate_sites': len(locations),
            'candidate_sites': [loc.id for loc in locations],
            'partition_counts': partition_counts,
            'flow_routes': flow_route_list,
            'shared_trunks': shared_trunks,
            'num_ecus_used': num_locations_used,  # For visualizer compatibility
            'num_partitions': num_partitions_opened,
            'hw_features': hw_opened,
            'interfaces': if_opened,
            'partition_cost': partition_cost,
            'site_cost': site_cost,
            'objective': 'LEGO Total Cost',
            'status': 'OPTIMAL'
        }
        return solution
